// Generated by OrchestKit Claude Plugin
// Created: 2026-09-03
//
// Pins the outline handling in src/workflows/write-sections.js.
//
// A live /academic-writer:write run on plugin 0.7.6 produced NO sections at
// all: the script read a flat `outline.units`, but the architect emits
// `sections[]` with an optional nested `units[]` and a section without one is
// itself the writer unit (architect.md:101, write/SKILL.md:387). So `units`
// was always [], `canRunDraftAndAudit` requires `units.length > 0`, and the
// whole draft-and-audit stage gated off with "no outline.units supplied".
//
// Separately, the per-unit prompt dropped `evidence`, `brief`, `depends_on`,
// `thesis_link` and `words` — fields section-writer.md:82 documents as
// required input, with no disk-read fallback anywhere.

const fs = require('fs');
const path = require('path');
const assert = require('assert');

const SRC = fs.readFileSync(
  path.join(__dirname, '..', 'src', 'workflows', 'write-sections.js'), 'utf8');

// flattenUnits is self-contained; lift it out rather than booting the runtime.
const start = SRC.indexOf('function flattenUnits');
const end = SRC.indexOf('const units = flattenUnits');
assert.ok(start !== -1 && end > start, 'flattenUnits not found in write-sections.js');
eval(SRC.slice(start, end));

const outline = {
  sections: [
    { id: 'I', title: 'Intro', argument_role: 'frames', thesis_link: 'tl-1',
      claim: 'c1', evidence: ['e1'] },
    { id: 'II', title: 'Body', argument_role: 'argues', thesis_link: 'tl-2',
      units: [
        { id: 'II.1', title: 'U1', claim: 'c2', evidence: ['e2'],
          depends_on: ['I'], thesis_link: 'tl-3', words: 350 },
        { id: 'II.2', title: 'U2', claim: 'c3', evidence: ['e3'],
          depends_on: ['II.1'], thesis_link: 'tl-4', words: 400 },
      ] },
  ],
};

const units = flattenUnits(outline);

assert.strictEqual(units.length, 3, 'a section without units is itself one writer unit');
assert.deepStrictEqual(units.map(u => u.id), ['I', 'II.1', 'II.2']);

// The fields that were dropped must survive flattening.
assert.deepStrictEqual(units[1].evidence, ['e2'], 'evidence must reach the writer');
assert.deepStrictEqual(units[1].depends_on, ['I']);
assert.strictEqual(units[1].thesis_link, 'tl-3');
assert.strictEqual(units[1].words, 350);

// Derived context the dispatch reference requires per spawn.
assert.strictEqual(units[1].parentSection.title, 'Body');
assert.deepStrictEqual(units[1].siblingUnitsSummary.map(s => s.id), ['II.2']);
assert.strictEqual(units[0].parentSection.title, 'Intro',
  'an undecomposed section is its own parent context');

// A caller that pre-flattens is still accepted, and an empty outline is empty.
assert.strictEqual(flattenUnits({ units: [{ id: 'X' }] }).length, 1);
assert.strictEqual(flattenUnits({}).length, 0);
assert.strictEqual(flattenUnits({ sections: [] }).length, 0);

// Every documented per-unit field appears in the prompt builder.
for (const label of ['EVIDENCE', 'DEPENDS_ON', 'THESIS_LINK', 'BRIEF', 'TARGET_WORDS']) {
  assert.ok(SRC.includes("'" + label + "'"),
    label + ' must be forwarded to the section-writer prompt');
}

console.log('test_write_sections_outline: 13 assertions OK');
